&#192; volont&#233; — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Monstre.html&quot; title=&quot;Charme-monstre&quot;&gt;charme-monstre&lt;/a&gt;&lt;/i&gt; (DD 20), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injonction-Supr&#234;me.html&quot; title=&quot;Injonction supr&#234;me&quot;&gt;injonction supr&#234;me&lt;/a&gt;&lt;/i&gt; (DD 21)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
3/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Feu.html&quot; title=&quot;Boule de feu&quot;&gt;boule de feu&lt;/a&gt;&lt;/i&gt; rapide (DD 19), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chant-De-Discorde.html&quot; title=&quot;Chant de discorde&quot;&gt;chant de discorde&lt;/a&gt;&lt;/i&gt; (DD 21), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domination.html&quot; title=&quot;Domination&quot;&gt;domination&lt;/a&gt;&lt;/i&gt; (DD 21), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rage.html&quot; title=&quot;Rage&quot;&gt;rage&lt;/a&gt;&lt;/i&gt; (DD 19)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exigence.html&quot; title=&quot;Exigence&quot;&gt;exigence&lt;/a&gt;&lt;/i&gt; (DD 24), &lt;a class=&quot;pagelink&quot; href=&quot;Convocation-(Capacit&#233;).html&quot; title=&quot;Convocation (Mag)&quot;&gt;convocation&lt;/a&gt; (niveau 6, 1 &lt;a class=&quot;pagelink&quot; href=&quot;Succube.html&quot; title=&quot;D&#233;mon, Succube&quot;&gt;succube&lt;/a&gt; 35%), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suggestion-De-Groupe.html&quot; title=&quot;Suggestion de groupe&quot;&gt;suggestion de groupe&lt;/a&gt;&lt;/i&gt; (DD 22)
&lt;/div&gt;
